<?xml version="1.0" encoding="UTF-8"?>
<mappingRoot xmlns="http://www.ibm.com/2008/ccl/Mapping" domainID="com.ibm.msl.mapping.xml" domainIDExtension="mb" mainMap="true" targetNamespace="default" version="8.0.5.0" xmlns:map="default">
    <input path="/Customer.xsd"/>
    <output path="/Customer.xsd"/>
    <generation engine="xquery"/>
    <mappingDeclaration name="CustomerMove">
        <input namespace="urn:customer" path="mb:msg(Customer,assembly,XMLNSC,Properties)" var="MessageAssembly"/>
        <output namespace="urn:customer" path="mb:msg(CustomerView,assembly,XMLNSC,Properties)" var="MessageAssembly1"/>
        <move>
            <input path="$MessageAssembly/Properties"/>
            <output path="$MessageAssembly1/Properties"/>
        </move>
        <move>
            <input path="$MessageAssembly/Customer/name"/>
            <output path="$MessageAssembly1/CustomerView/displayName"/>
        </move>
        <move>
            <input path="$MessageAssembly/Customer/balance"/>
            <output path="$MessageAssembly1/CustomerView/amount"/>
        </move>
    </mappingDeclaration>
</mappingRoot>
